    adcs x9, x9, x21
    lsr x21, x25, #40
    adc x11, x28, x11
    and x28, x25, #0xffffffffff
    add x21, x21, x21, lsl         #4
    add x28, x28, x28, lsl         #4
    add x21, x21, x28, lsr         #40
    lsl x28, x28, #24
    adds x11, x11, x28
    adc x28, x21, xzr
    mov x21, #0x11000000
    cmp x28, x21
    csel x21, x21, xzr, cs
    sbcs x15, x15, xzr
    sbcs x6, x6, xzr
    sbcs x25, x24, xzr
    stp x15, x6, [x0, #88]
    sbcs x22, x19, xzr
    sbcs x8, x8, xzr
    stp x25, x22, [x0, #104]
    sbcs x19, x17, xzr
    sbcs x17, x26, xzr
    stp x8, x19, [x0, #120]
    sbcs x12, x12, xzr
    sbcs x26, x9, xzr
    stp x17, x12, [x0, #136]
    sbcs x11, x11, xzr
    sbc x9, x28, xzr
    stp x26, x11, [x0, #152]
    sub x9, x9, x21
    str x9, [x0, #168]
    ldp d14, d15, [sp, #128]
    ldp d12, d13, [sp, #112]
    ldp d10, d11, [sp, #96]
    ldp d8, d9, [sp, #80]
    ldp x27, x28, [sp, #64]
    ldp x25, x26, [sp, #48]
    ldp x23, x24, [sp, #32]
    ldp x21, x22, [sp, #16]
    ldp x19, x20, [sp], #144
    ret

#ifndef SQISIGN_USE_ARCHIVED_FP2_SQR
//***********************************************************************
//  Squaring in GF(p^2), both components
//  Operation: c0 = (a0+a1) x (a0-a1) ; c1 = 2 a0 x a1
//  Inputs: a = [a1, a0] stored in [x1]
//  Output: c = [c1, c0] stored in [x0]  (c may alias a)
//  Register allocation: multiplicand (d = a0-a1+2p, then a1) = x3..x13;
//                       acc z0..z11 = x14..x17,x19..x26,
//                       scalar bi = x27, MULADD temp x28;
//                       scalars streamed from [sp].
//  Stack: [sp+0 .. 88) holds s = a0+a1 (raw);
//         [sp+88 .. 176) holds t = 2*a0 (raw; self-add, EXTR is slow).
//***********************************************************************
.global fp2_sqr
.p2align 6
fp2_sqr:
    sub   sp, sp, #256               // 176 for s + t buffer + 80 for callee saves
    stp   x19, x20, [sp, #176]
    stp   x21, x22, [sp, #192]
    stp   x23, x24, [sp, #208]
    stp   x25, x26, [sp, #224]
    stp   x27, x28, [sp, #240]

    // t = 2*a0 (raw) -> [sp+88] ; a0 stays in x3..x13
    ldp   x3, x4, [x1]
    ldp   x5, x6, [x1, #16]
    ldp   x7, x8, [x1, #32]
    ldp   x9, x10, [x1, #48]
    ldp   x11, x12, [x1, #64]
    ldr   x13, [x1, #80]
    adds  x14, x3, x3
    adcs  x15, x4, x4
    adcs  x16, x5, x5
    adcs  x17, x6, x6
    adcs  x19, x7, x7
    adcs  x20, x8, x8
    adcs  x21, x9, x9
    adcs  x22, x10, x10
    adcs  x23, x11, x11
    adcs  x24, x12, x12
    adc   x25, x13, x13
    stp   x14, x15, [sp, #88]
    stp   x16, x17, [sp, #104]
    stp   x19, x20, [sp, #120]
    stp   x21, x22, [sp, #136]
    stp   x23, x24, [sp, #152]
    str   x25, [sp, #168]
    // s = a0 + a1 (raw) -> [sp]
    ldp   x14, x15, [x1, #88]
    ldp   x16, x17, [x1, #104]
    ldp   x19, x20, [x1, #120]
    ldp   x21, x22, [x1, #136]
    ldp   x23, x24, [x1, #152]
    ldr   x25, [x1, #168]
    adds  x14, x14, x3
    adcs  x15, x4, x15
    adcs  x16, x5, x16
    adcs  x17, x6, x17
    adcs  x19, x7, x19
    adcs  x20, x8, x20
    adcs  x21, x9, x21
    adcs  x22, x10, x22
    adcs  x23, x11, x23
    adcs  x24, x12, x24
    adc   x25, x25, x13
    stp   x14, x15, [sp]
    stp   x16, x17, [sp, #16]
    stp   x19, x20, [sp, #32]
    stp   x21, x22, [sp, #48]
    stp   x23, x24, [sp, #64]
    str   x25, [sp, #80]
    // d = a0 - a1 + 2p (raw) -> x3..x13 ; p2 = 2p = {-2,-1,...,0x0000000021FFFFFF}
    ldp   x14, x15, [x1, #88]
    subs  x3, x3, x14
    sbcs  x4, x4, x15
    ldp   x14, x15, [x1, #104]
    sbcs  x5, x5, x14
    sbcs  x6, x6, x15
    ldp   x14, x15, [x1, #120]
    sbcs  x7, x7, x14
    sbcs  x8, x8, x15
    ldp   x14, x15, [x1, #136]
    sbcs  x9, x9, x14
    sbcs  x10, x10, x15
    ldp   x14, x15, [x1, #152]
    sbcs  x11, x11, x14
    sbcs  x12, x12, x15
    ldr   x14, [x1, #168]
    sbcs  x13, x13, x14
    mov   x14, #-2
    adds  x3, x3, x14
    mov   x14, #-1
    adcs  x4, x4, x14
    adcs  x5, x5, x14
    adcs  x6, x6, x14
    adcs  x7, x7, x14
    adcs  x8, x8, x14
    adcs  x9, x9, x14
    adcs  x10, x10, x14
    adcs  x11, x11, x14
    adcs  x12, x12, x14
    movz  x14, #0xffff
    movk  x14, #0x21ff, lsl #16      // 2p[10]
    adc   x13, x13, x14

    // [x14:x26] <- z = d x s0
    ldr   x27, [sp]
    MUL64x704  x14,x15,x16,x17,x19,x20,x21,x22,x23,x24,x25,x26, x3,x4,x5,x6,x7,x8,x9,x10,x11,x12,x13, x27, x28
    FPMUL704x704  sp, x3,x4,x5,x6,x7,x8,x9,x10,x11,x12,x13, x14,x15,x16,x17,x19,x20,x21,x22,x23,x24,x25,x26, x27, x28

    // c0 -> [x0] (a0's slot; a1 is still intact if c == a)
    stp   x26, x14, [x0]
    stp   x15, x16, [x0, #16]
    stp   x17, x19, [x0, #32]
    stp   x20, x21, [x0, #48]
    stp   x22, x23, [x0, #64]
    str   x24, [x0, #80]

    // [x26, x14:x25] <- z = a1 x t0
    ldp   x3, x4, [x1, #88]
    ldp   x5, x6, [x1, #104]
    ldp   x7, x8, [x1, #120]
    ldp   x9, x10, [x1, #136]
    ldp   x11, x12, [x1, #152]
    ldr   x13, [x1, #168]
    add   x1, sp, #88                // x1 is dead after the a1 load: reuse it as the t pointer
    ldr   x27, [x1]
    MUL64x704  x26,x14,x15,x16,x17,x19,x20,x21,x22,x23,x24,x25, x3,x4,x5,x6,x7,x8,x9,x10,x11,x12,x13, x27, x28
    FPMUL704x704  x1, x3,x4,x5,x6,x7,x8,x9,x10,x11,x12,x13, x26,x14,x15,x16,x17,x19,x20,x21,x22,x23,x24,x25, x27, x28

    stp   x25, x26, [x0, #88]
    stp   x14, x15, [x0, #104]
    stp   x16, x17, [x0, #120]
    stp   x19, x20, [x0, #136]
    stp   x21, x22, [x0, #152]
    str   x23, [x0, #168]
    ldp   x27, x28, [sp, #240]
    ldp   x25, x26, [sp, #224]
    ldp   x23, x24, [sp, #208]
    ldp   x21, x22, [sp, #192]
    ldp   x19, x20, [sp, #176]
    add   sp, sp, #256
    ret
#endif

//***********************************************************************
//  Field multiplication in GF(p)
//  Operation: c = a x b mod p
//  Inputs: a stored in [x1], b stored in [x2]
//  Output: c stored in [x0]
//  Register allocation: a (resident) = x3..x13;
//                       acc z0..z11 = x14..x17,x19..x26,
//                       scalar bi = x27, MULADD temp x28;
//                       the reduction borrows bi (dead there).
//***********************************************************************
.global fp_mul
.p2align 6
fp_mul:
    stp   x19, x20, [sp, #-80]!
    stp   x21, x22, [sp, #16]
    stp   x23, x24, [sp, #32]
    stp   x25, x26, [sp, #48]
    stp   x27, x28, [sp, #64]
    ldp   x3, x4, [x1]
    ldp   x5, x6, [x1, #16]
    ldp   x7, x8, [x1, #32]
    ldp   x9, x10, [x1, #48]
    ldp   x11, x12, [x1, #64]
    ldr   x13, [x1, #80]

    // [x14:x26] <- z = a x b0
    ldr   x27, [x2]
    MUL64x704  x14,x15,x16,x17,x19,x20,x21,x22,x23,x24,x25,x26, x3,x4,x5,x6,x7,x8,x9,x10,x11,x12,x13, x27, x28
    FPMUL704x704  x2, x3,x4,x5,x6,x7,x8,x9,x10,x11,x12,x13, x14,x15,x16,x17,x19,x20,x21,x22,x23,x24,x25,x26, x27, x28

    stp   x26, x14, [x0]
    stp   x15, x16, [x0, #16]
    stp   x17, x19, [x0, #32]
    stp   x20, x21, [x0, #48]
    stp   x22, x23, [x0, #64]
    str   x24, [x0, #80]
    ldp   x27, x28, [sp, #64]
    ldp   x25, x26, [sp, #48]
    ldp   x23, x24, [sp, #32]
    ldp   x21, x22, [sp, #16]
    ldp   x19, x20, [sp], #80
    ret

.global fp_sqr
.p2align 6
fp_sqr:
    mov   x2, x1
    b     fp_mul
